#!/usr/bin/env python3
"""Deepen the late-Wanli Liaodong rupture and the Sahu campaign."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "App/Resources/history.json"
NARRATION = ROOT / "App/Resources/narration_manifest.json"


def upsert(items, item, key="id"):
    for i, old in enumerate(items):
        if old.get(key) == item[key]:
            items[i] = item
            return
    items.append(item)


def add_unique(items, *values):
    for value in values:
        if value not in items:
            items.append(value)


def sec(sid, title, text, sources, events, people):
    return {"id": sid, "title": title, "text": text, "kind": "史实与解读", "sources": sources, "events": events, "people": people}


def article(person, title, dek, sections):
    sources = []
    for item in sections:
        add_unique(sources, *item["sources"])
    return {"person": person, "title": title, "dek": dek, "sections": sections, "sources": sources}


def event(eid, year, sort_year, title, category, body, impact, people, sources, kind):
    return {"id": eid, "year": year, "sortYear": sort_year, "title": title, "category": category, "body": body, "impact": impact, "people": people, "sources": sources, "kind": kind}


def association(data, source, target, role, inverse, period, note, sources):
    item = {"from": source, "to": target, "role": role, "inverse": inverse, "period": period, "note": note, "sources": sources}
    for i, old in enumerate(data["associations"]):
        if old["from"] == source and old["to"] == target:
            data["associations"][i] = item
            return
    data["associations"].append(item)


